import json
# Panel 6x6, bounds from marker group coordinates; expand each color within its markers' bounding rectangle.
R,C=6,6
marks={2:[(1,0),(1,4),(3,0)],3:[(0,2),(4,2)]}
paint={}
for color,pts in marks.items():
 for r in range(min(x for x,y in pts),max(x for x,y in pts)+1):
  for c in range(min(y for x,y in pts),max(y for x,y in pts)+1):
   paint[(r,c)]=paint.get((r,c),0)+color
p=[[6 if paint.get((r,c))==5 else (2 if paint.get((r,c))==2 else 3 if paint.get((r,c))==3 else 0) for c in range(C)] for r in range(R)]
s=[4,4,4,4,4,3]
g=[]
for r,h in enumerate(s):
 for _ in range(h):
  row=[]
  for c,w in enumerate(s):
   row.extend([p[r][c]]*w)
   if c<5: row.append(8)
  g.append(row)
 if r<5:g.append([8]*28)
assert len(g)==28 and all(len(row)==28 for row in g)
print(json.dumps(g,separators=(',',':')))
